import{_ as a,o as n,c as s,ag as t}from"./chunks/framework.BbSdnUwJ.js";const g=JSON.parse('{"title":"Reading diagnostics","description":"How the compiler reports a problem, what each part of a diagnostic says, and how errors, warnings and exit codes relate.","frontmatter":{"title":"Reading diagnostics","description":"How the compiler reports a problem, what each part of a diagnostic says, and how errors, warnings and exit codes relate."},"headers":[],"relativePath":"guide/basics/diagnostics.md","filePath":"guide/basics/diagnostics.md"}'),o={name:"guide/basics/diagnostics.md"};function i(r,e,l,d,p,c){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="reading-diagnostics" tabindex="-1">Reading diagnostics <a class="header-anchor" href="#reading-diagnostics" aria-label="Permalink to &quot;Reading diagnostics&quot;">​</a></h1><p>When something is wrong, the compiler says what, where and what to change, in the layout rustc and ruff use.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error[name.unknown_reference]: Navigate.goal: nothing named &#39;gaol&#39; matches @world/&lt;goal or entity&gt;</span></span>
<span class="line"><span>  --&gt; demo.task:3:25</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>3 |         Navigate(goal = @world/gaol)</span></span>
<span class="line"><span>  |                         ^^^^^^^^^^^ not declared</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  = help: did you mean &#39;goal&#39;?</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Part</th><th>Says</th></tr></thead><tbody><tr><td><code>error[name.unknown_reference]</code></td><td>The level and the code. The code is stable; tools and tests match on it.</td></tr><tr><td>The message</td><td>The cause, in one sentence.</td></tr><tr><td><code>--&gt; demo.task:3:25</code></td><td>The file, line and column of the cause.</td></tr><tr><td>The excerpt</td><td>The source line, with the exact bytes underlined.</td></tr><tr><td><code>= help:</code></td><td>What to change.</td></tr><tr><td><code>= note:</code></td><td>The facts the decision rested on.</td></tr></tbody></table><p>The cause can be in a library as well as in the program: a problem with a part points into its <code>component.yaml</code>.</p><h2 id="errors-and-warnings" tabindex="-1">Errors and warnings <a class="header-anchor" href="#errors-and-warnings" aria-label="Permalink to &quot;Errors and warnings&quot;">​</a></h2><p>An error blocks: nothing is written. A warning does not. A validation rule that cannot decide, usually because a part does not state something, is a warning that says so:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>warning[validation.assembly.footprint_known]: cannot decide: part &#39;imu_basic&#39; of &#39;imu&#39; declares no collision box, so the footprint may be larger than the known shapes</span></span>
<span class="line"><span>   --&gt; demo.core:12:5</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>12 |     IMU imu(ref = &quot;imu_basic&quot;, glue = (0, 0.0001, 0.0344, 0, 0, -1))</span></span>
<span class="line"><span>   |     ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ no collision shape</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   = help: add a \`collision\` box to the part&#39;s component.yaml</span></span>
<span class="line"><span>   = note: evidence: x in [-0.177, 0.177] m, y in [-0.173, 0.173] m from chassis, wheel_lf, wheel_lb, wheel_rf, wheel_rb</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Checked demo.core demo.world demo.task (9 checks, 1 undecided)</span></span></code></pre></div><p><code>--warnings-as-errors</code> makes every warning block, and each one says so in a note.</p><h2 id="everything-at-once" tabindex="-1">Everything at once <a class="header-anchor" href="#everything-at-once" aria-label="Permalink to &quot;Everything at once&quot;">​</a></h2><p>The parser stops at the first syntax error. Every later phase checks the whole program and reports every problem it finds, so one compile shows everything it can:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error[validation.assembly.wheel_mounts_filled]: a Mecanum_four_wheel chassis needs a wheel on &#39;front_left_wheel&#39;; none is placed there</span></span>
<span class="line"><span>  --&gt; demo.core:5:5</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>5 |     Mecanum_four_wheel chassis(ref = &quot;tslot_1515_drone&quot;)</span></span>
<span class="line"><span>  |     ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ no wheel on &#39;front_left_wheel&#39;</span></span>
<span class="line"><span>  |</span></span>
<span class="line"><span>  = help: add a wheel with glue = (0.1275, 0.1494, -0.0216, 0, 1, 0)</span></span>
<span class="line"><span>  = note: evidence: 3 rolling wheels for 4 mounts</span></span>
<span class="line"><span></span></span>
<span class="line"><span>error[validation.assembly.glue_on_connector]: the glue of &#39;wheel_lf&#39; matches no connector of the chassis; the nearest is &#39;wheel_mount_front_left&#39;, 0.008 m away with direction cosine 1.00</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>error: 2 errors; demo.core demo.world demo.task did not compile</span></span></code></pre></div><p>One misplaced wheel produced both: the glue matches no connector, so the mount it was meant for is empty.</p><h2 id="for-tools" tabindex="-1">For tools <a class="header-anchor" href="#for-tools" aria-label="Permalink to &quot;For tools&quot;">​</a></h2><p><code>--json</code> writes the whole result to stdout: every diagnostic, every validation rule with its status and evidence, and the files written. <code>--color never</code> turns colour off; it is also off when <code>NO_COLOR</code> is set or the output is not a terminal.</p><table tabindex="0"><thead><tr><th>Exit status</th><th>Means</th></tr></thead><tbody><tr><td>0</td><td>Nothing blocked; warnings may have been printed</td></tr><tr><td>1</td><td>A diagnostic blocked</td></tr><tr><td>2</td><td>The command line itself was wrong</td></tr></tbody></table><p><a href="./../../reference/diagnostics.html">Diagnostics</a> in the reference specifies every field and code.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./running.html">Running the output</a> explains what the compiler writes and how to launch it.</p>`,19)])])}const u=a(o,[["render",i]]);export{g as __pageData,u as default};
